using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static class PreserveMountainCutNative {public static string Main(){var live=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var targets=Object.FindObjectsByType<MeshFilter>().Where(m=>m.name.StartsWith("Ground_Mountain_")&&AssetDatabase.GetAssetPath(m.sharedMesh).Contains("MountainCut/")).ToDictionary(m=>m.name);string tmp="Assets/Scenes/MountainCutPrevious.unity";File.Copy("Temp/MountainCutPrevious.unity",tmp,true);AssetDatabase.ImportAsset(tmp);var old=EditorSceneManager.OpenScene(tmp,OpenSceneMode.Additive);int n=0;foreach(var m in old.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()))if(targets.TryGetValue(m.name,out var target)){target.sharedMesh=m.sharedMesh;target.GetComponent<MeshCollider>().sharedMesh=m.sharedMesh;n++;}EditorSceneManager.CloseScene(old,true);AssetDatabase.DeleteAsset(tmp);EditorSceneManager.MarkSceneDirty(live);EditorSceneManager.SaveScene(live);AssetDatabase.SaveAssets();File.WriteAllText("Docs/MountainCut/native-terrain-preserved.txt","Retained original native mountain meshes outside the necessary upper-shoulder clip: "+n);return "Preserved original surrounding native terrain: "+n;}}
